'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var realf = require( '@stdlib/complex/float32/real' );
var real = require( '@stdlib/complex/float64/real' );
var factory = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the returned constructor is an `of` method for creating a complex number array from a variable number of arguments (complex128)', function test( t ) {
	var Complex128Array;
	var arr;

	Complex128Array = factory( 'complex128' );

	t.strictEqual( hasOwnProp( Complex128Array, 'of' ), true, 'has property' );
	t.strictEqual( isFunction( Complex128Array.of ), true, 'has method' );

	arr = Complex128Array.of();
	t.strictEqual( arr instanceof Complex128Array, true, 'returns expected value' );

	t.end();
});

